import os
import numpy as np
SKILL_CONTENT = os.environ.get("SKILL_CONTENT", "")
def _atomic(writer, path):
    tmp = path + ".tmp"
    with open(tmp, "wb") as handle:
        writer(handle)
    os.replace(tmp, path)
def write_npy(path, array):
    return _atomic(lambda h: np.save(h, array), path)
def main():
    write_npy(os.path.join(SKILL_CONTENT, "bge.npy"), None)
